/****************************************************************************
 * ltr553_main
 ****************************************************************************/

int main(int argc, FAR char *argv[]) {
  FAR const struct orb_metadata *light_meta, *prox_meta;
  struct sensor_light light_data;
  struct sensor_prox prox_data;
  struct pollfd fds[2];
  int ret = OK;
  int light_fd, prox_fd;
  int i;

  light_meta = ORB_ID(sensor_light);
  light_fd = orb_subscribe_multi(light_meta, 0);
  if (light_fd < 0) {
    printf("sensor light subscribe error! return:%d\n", light_fd);
    return light_fd;
  }

  prox_meta = ORB_ID(sensor_prox);
  prox_fd = orb_subscribe_multi(prox_meta, 0);
  if (prox_fd < 0) {
    printf("sensor prox subscribe error! return:%d\n", prox_fd);
    orb_unsubscribe(light_fd);
    return prox_fd;
  }

  fds[0].fd = light_fd;
  fds[0].events = POLLIN;
  fds[1].fd = prox_fd;
  fds[1].events = POLLIN;

  for (i = 0; i < READ_TIMES; i++) {
    if (poll(fds, 2, LIGHT_TIMEOUT) > 0) {
      if (fds[0].revents & POLLIN) {
        ret = orb_copy(light_meta, light_fd, &light_data);
#ifdef CONFIG_DEBUG_UORB
        if (ret == OK && light_meta->o_format != NULL) {
          orb_info(light_meta->o_format, light_meta->o_name, &light_data);
        }
#endif
      }

      if (fds[1].revents & POLLIN) {
        ret = orb_copy(prox_meta, prox_fd, &prox_data);
#ifdef CONFIG_DEBUG_UORB
        if (ret == OK && prox_meta->o_format != NULL) {
          orb_info(prox_meta->o_format, prox_meta->o_name, &prox_data);
        }
#endif
      }
    } else if (ret == 0) {
      printf("Poll timeout %d/%d\n", i + 1, READ_TIMES);
      continue;
    } else if (errno != EINTR) {
      printf("Poll error: %d\n", errno);
      break;
    }
  }

  orb_unsubscribe(light_fd);
  orb_unsubscribe(prox_fd);
  printf("sensor ltr553 read examples exit.\n");

  return ret;
}

 * Name: sensor_register
 *
 * Description:
 *   This function binds an instance of a "lower half" Sensor driver with the
 *   "upper half" Sensor device and registers that device so that can be used
 *   by application code.
 *
 *   We will register the chararter device by node name format based on the
 *   type of sensor. Multiple types of the same type are distinguished by
 *   numbers. eg: accel0, accel1
 *
 * Input Parameters:
 *   dev   - A pointer to an instance of lower half sensor driver. This
 *           instance is bound to the sensor driver and must persists as long
 *           as the driver persists.
 *   devno - The user specifies which device of this type, from 0. If the
 *           devno alerady exists, -EEXIST will be returned.
 *
 * Returned Value:
 *   OK if the driver was successfully register; A negated errno value is
 *   returned on any failure.
 *
 ****************************************************************************/

int sensor_register(FAR struct sensor_lowerhalf_s *lower, int devno)
{
  FAR char *path;
  int ret;

  DEBUGASSERT(lower != NULL);

  path = lib_get_tempbuffer(PATH_MAX);
  if (path == NULL)
    {
      return -ENOMEM;
    }

  snprintf(path, PATH_MAX, DEVNAME_FMT,
           g_sensor_meta[lower->type].name,
           devno);
  ret = sensor_custom_register(lower, path,
                               g_sensor_meta[lower->type].esize);
  lib_put_tempbuffer(path);
  return ret;
}

/****************************************************************************
 * Name: sensor_custom_register
 *
 * Description:
 *   This function binds an instance of a "lower half" Sensor driver with the
 *   "upper half" Sensor device and registers that device so that can be used
 *   by application code.
 *
 *   You can register the character device type by specific path and esize.
 *   This API corresponds to the sensor_custom_unregister.
 *
 * Input Parameters:
 *   dev   - A pointer to an instance of lower half sensor driver. This
 *           instance is bound to the sensor driver and must persists as long
 *           as the driver persists.
 *   path  - The user specifies path of device. ex: /dev/uorb/xxx.
 *   esize - The element size of intermediate circular buffer.
 *
 * Returned Value:
 *   OK if the driver was successfully register; A negated errno value is
 *   returned on any failure.
 *
 ****************************************************************************/

int sensor_custom_register(FAR struct sensor_lowerhalf_s *lower,
                           FAR const char *path, size_t esize)
{
  FAR struct sensor_upperhalf_s *upper;
  int ret = -EINVAL;

  DEBUGASSERT(lower != NULL);

  if (lower->type >= SENSOR_TYPE_COUNT || !esize)
    {
      snerr("ERROR: type is invalid\n");
      return ret;
    }

  /* Allocate the upper-half data structure */

  upper = kmm_zalloc(sizeof(struct sensor_upperhalf_s));

  return -EINVAL;
}

/****************************************************************************
 * Name: ltr553_register
 ****************************************************************************/

int ltr553_register(int devno, FAR struct i2c_master_s *i2c) {
  FAR struct ltr553_dev_s *priv;
  int ret = OK;

  DEBUGASSERT(i2c != NULL);

  /* Initialize the LTR553 device structure */
  priv = kmm_zalloc(sizeof(struct ltr553_dev_s));
  if (priv == NULL) {
    return -ENOMEM;
  }

  /* 设置全局指针 */
  g_ltr553_dev = priv;

  priv->i2c = i2c;
  priv->addr = LTR553_I2C_ADDR;
  priv->freq = CONFIG_LTR553_I2C_FREQUENCY;
  priv->enabled = false;
  priv->sleeping = true;

  /* 设置默认配置 */
  priv->als_gain = LTR553_ALS_GAIN_1X;
  priv->als_integration_time = LTR553_ALS_INTEG_100MS;
  priv->als_measurement_rate = LTR553_ALS_RATE_100MS;
  priv->ps_gain = LTR553_PS_GAIN_16X;
  priv->ps_led_current = 0x7F;
  priv->ps_pulses = 1;

  nxmutex_init(&priv->dev_lock);
  nxsem_init(&priv->run, 0, 0);

  /* Check Device ID */
  ret = ltr553_checkid(priv);
  if (ret < 0) {
    goto err_init;
  }

  /* 软件复位传感器 */
  ret = ltr553_set_reg8(priv, LTR553_ALS_CONTR, 0x02); /* 软件复位位 */
  if (ret >= 0) {
    nxsig_usleep(10000);                                 /* 等待10ms */
    ret = ltr553_set_reg8(priv, LTR553_ALS_CONTR, 0x00); /* 清除复位位 */
  }

  if (ret < 0) {
    goto err_init;
  }

  /* 初始化ALS传感器 */
  priv->sensors[LTR553_SENSOR_ALS].type = LTR553_SENSOR_ALS;
  priv->sensors[LTR553_SENSOR_ALS].enabled = false;
  priv->sensors[LTR553_SENSOR_ALS].lower.ops = &g_ltr553_als_ops;
  priv->sensors[LTR553_SENSOR_ALS].lower.type = SENSOR_TYPE_LIGHT;

  ret = sensor_register(&priv->sensors[LTR553_SENSOR_ALS].lower, devno);
  if (ret < 0) {
    goto err_init;
  }

  /* 初始化PS传感器 */
  priv->sensors[LTR553_SENSOR_PS].type = LTR553_SENSOR_PS;
  priv->sensors[LTR553_SENSOR_PS].enabled = false;
  priv->sensors[LTR553_SENSOR_PS].lower.ops = &g_ltr553_ps_ops;
  priv->sensors[LTR553_SENSOR_PS].lower.type = SENSOR_TYPE_PROXIMITY;

  ret = sensor_register(&priv->sensors[LTR553_SENSOR_PS].lower, devno);
  if (ret < 0) {
    goto err_register;
  }

  /* 创建轮询线程 */
  ret = kthread_create("ltr553_thread", SCHED_PRIORITY_DEFAULT,
                       CONFIG_SENSORS_LTR553_THREAD_STACKSIZE, ltr553_thread,
                       NULL);
  if (ret < 0) {
    goto err_register_ps;
  }

  return OK;

err_register_ps:
  sensor_unregister(&priv->sensors[LTR553_SENSOR_PS].lower, devno);
err_register:
  sensor_unregister(&priv->sensors[LTR553_SENSOR_ALS].lower, devno);
err_init:
  g_ltr553_dev = NULL;
  nxsem_destroy(&priv->run);
  nxmutex_destroy(&priv->dev_lock);

