static int ltr553_checkid(FAR struct ltr553_dev_s *priv) {
  uint8_t devid;
  int ret;

  ret = ltr553_get_reg8(priv, LTR553_PART_ID_REG, &devid);
  if (ret < 0) {
    return ret;
  }

  sninfo("devid: 0x%02x\n", devid);
  return (devid != LTR553_PART_ID) ? -ENODEV : OK;
}

