         * here, which is also the cheapest state to render -- exactly what a
         * board being refused service should be doing. */
        t.eye_open = 45;   t.brow_dy = -5;
        t.brow_tilt = -18; t.brow_tilt_r = -18;
        t.mouth_curve = -45; t.pupil_dy = 4;
